sys_ui_action.script:
/* eslint no-undef: "error" */

function deleteSearchHistory() {
	/* global GlideModal, g_list */
	const target = g_list.getChecked() ? 'selected' : 'whole';

	const gm = new GlideModal('glide_confirm_standard'); 
	gm.setTitle('Search History Clear Confirmation');
	gm.setPreference('title', 'Do you really want to clear the ' + target + ' search history?');
	gm.setPreference('warning', true);
	gm.setPreference('onPromptComplete', function () {
		// Note: The adding 'sysverb' to skip the 'record selection' check.
		g_list.action('1c56ec1683f276504967cbb6feaad3a6', 'sysverb');
	});
	gm.render();
}

if (typeof window === 'undefined') {
	/* global gs */
	/* global action, x_itx_codesearch */
	const checked = action.getGlideURI().get('sysparm_checked_items');
	const result = x_itx_codesearch.CodeSearchWorker.clear(checked);
	if (result.status != 'success') {
		gs.addErrorMessage(result.message);
	}

	action.setRedirectURL('x_itx_codesearch_st_search_history_list.do');
}
